import java.util.*;
public class PublicChecks {public record Observation(String actual,boolean passed){}
static final String NORMAL_NAME="Порядок и повторное место";
static final String NORMAL_WHAT="FIFO и два типа после извлечения из полной очереди.";
static final String NORMAL_INPUT="String[3]: А,Б,В/get2/Г,Д/get3; Integer[2]:10,20/get/30/get2";
static final String NORMAL_EXPECTED="А,Б,В,Г,Д;10,20,30; новые добавления успешны.";
static final String BOUNDARY_NAME="Вместимость один и отказы";
static final String BOUNDARY_WHAT="Начальная пустота на массиве99, отказ полной очереди сохраняет7.";
static final String BOUNDARY_INPUT="Integer[]{99}:get/put7/put8/get/put8/get/get";
static final String BOUNDARY_EXPECTED="null с сообщением; отказ put8 с сообщением;7;8;null с сообщением; исходное99 не извлекается.";
public static Observation observeNormal(){Object s=TaskBinding.publicQueue(0,new String[3]);Object i=TaskBinding.publicQueue(1,new Integer[2]);Object[] got=new Object[8];String output=PublicMessages.capture(()->{TaskBinding.put(s,"А");TaskBinding.put(s,"Б");TaskBinding.put(s,"В");got[0]=TaskBinding.get(s);got[1]=TaskBinding.get(s);TaskBinding.put(s,"Г");TaskBinding.put(s,"Д");for(int k=2;k<5;k++)got[k]=TaskBinding.get(s);TaskBinding.put(i,10);TaskBinding.put(i,20);got[5]=TaskBinding.get(i);TaskBinding.put(i,30);got[6]=TaskBinding.get(i);got[7]=TaskBinding.get(i); });Object[] expected={"А","Б","В","Г","Д",10,20,30};return new Observation("Извлечено="+Arrays.toString(got)+"; вывод (текст свободен)="+PublicOutput.escaped(output),Arrays.equals(got,expected));}
public static Observation observeBoundary(){Object q=TaskBinding.publicQueue(1,new Integer[]{99});Object[] got=new Object[4];String initial=PublicMessages.capture(()->got[0]=TaskBinding.get(q));String add=PublicMessages.capture(()->TaskBinding.put(q,7));String full=PublicMessages.capture(()->TaskBinding.put(q,8));String middle=PublicMessages.capture(()->{got[1]=TaskBinding.get(q);TaskBinding.put(q,8);got[2]=TaskBinding.get(q);});String last=PublicMessages.capture(()->got[3]=TaskBinding.get(q));return new Observation("Извлечено="+Arrays.toString(got)+"; первый отказ="+PublicOutput.escaped(initial)+"; полный put="+PublicOutput.escaped(full)+"; успешные действия="+PublicOutput.escaped(add+middle)+"; последний отказ="+PublicOutput.escaped(last),Arrays.equals(got,new Object[]{null,7,8,null})&&!initial.isBlank()&&!last.isBlank()&&!full.isBlank());}
public static void checkNormal(Observation o){if(!o.passed())throw new AssertionError("Сопоставьте обычное наблюдение с условием.");}
public static void checkBoundary(Observation o){if(!o.passed())throw new AssertionError("Сопоставьте опубликованную границу с условием.");}
static int example(boolean normal){System.out.println("Сценарий: "+(normal?NORMAL_NAME:BOUNDARY_NAME));System.out.println("Что наблюдаем: "+(normal?NORMAL_WHAT:BOUNDARY_WHAT));System.out.println("Вход/действие: "+(normal?NORMAL_INPUT:BOUNDARY_INPUT));System.out.println("Ожидается: "+(normal?NORMAL_EXPECTED:BOUNDARY_EXPECTED));try{var o=normal?observeNormal():observeBoundary();System.out.println("Получено: "+o.actual());System.out.println(o.passed()?"Статус: наблюдаемое свойство соответствует; исходник и объяснение оценивает преподаватель.":"Статус: наблюдаемое свойство не соответствует.");return o.passed()?0:1;}catch(LinkageError e){System.out.println("Статус: привязка или среда не подготовлена; требуется ручная проверка, оценки нет.");return 2;}catch(RuntimeException e){System.out.println("Статус: операция или пример привязки не завершены корректно. Тип: "+e.getClass().getSimpleName());return 1;}catch(Error e){System.out.println("Статус: ошибка выполнения операции. Тип: "+e.getClass().getSimpleName());return 1;}}
public static void main(String[] args){int status=Math.max(example(true),example(false));if(status!=0)System.exit(status);}}
